(()=>{const e=document.querySelector(".menu__btn"),n=document.querySelector(".navigation"),t=window.matchMedia("(min-width: 768px)");e.addEventListener("click",function(){n.classList.toggle("navigation--active")}),t.addEventListener("change",function(e){e.matches&&n.classList.remove("navigation--active")}),new ResizeObserver(function(){document.body.classList.add("resizing"),requestAnimationFrame(function(){document.body.classList.remove("resizing")})}).observe(document.body)})();